<?php

class DataReader {
    private $reader;
    private $st;

    public function __construct($reader) {
        $this->reader = $reader;
        $this->st = null;
    }

    public function next(): ?string {
        while ($this->st === null || !$this->st->hasMoreTokens()) {
            $line = fgets($this->reader);
            if ($line === false) {
                return null;
            }
            $this->st = new StringTokenizer($line);
        }
        return $this->st->nextToken();
    }

    public function nextToken(): string {
        return $this->next();
    }

    public function nextInt(): int {
        return (int)$this->nextToken();
    }

    public function nextLong(): int {
        return (int)$this->nextToken();
    }

    public function readIntArray(int $n): array {
        $result = [];
        for ($i = 0; $i < $n; $i++) {
            $result[] = $this->nextInt();
        }
        return $result;
    }

    public function nextLine(): ?string {
        return fgets($this->reader);
    }
}

class StringTokenizer {
    private $tokens;
    private $index;

    public function __construct(string $line) {
        $this->tokens = array_filter(explode(' ', trim($line)));
        $this->index = 0;
    }

    public function hasMoreTokens(): bool {
        return $this->index < count($this->tokens);
    }

    public function nextToken(): string {
        return $this->tokens[$this->index++];
    }
}

function toYesNo(bool $value): string {
    return $value ? "YES" : "NO";
}

function solve(DataReader $reader, $out): void {
    $n = $reader->nextInt();
    $k = $reader->nextInt();

    $s = $reader->nextToken();

    $used = array_fill(0, $n, false);

    $dfs = function (int $u) use (&$dfs, $n, $k, $s, &$used): bool {
        if ($u < 0 || $u >= $n || $used[$u] || $s[$u] === '#') {
            return false;
        }
        if ($s[$u] === 'T') {
            return true;
        }
        $used[$u] = true;

        return $dfs($u - $k) || $dfs($u + $k);
    };

    $start = strpos($s, 'G');
    fwrite($out, toYesNo($dfs($start)) . "\n");
}

function main(): void {
    $onlineJudge = getenv('ONLINE_JUDGE') !== false;

    if (!$onlineJudge) {
        $in = fopen('input.txt', 'r');
        $out = fopen('output.txt', 'w');
    } else {
        $in = fopen('php://stdin', 'r');
        $out = fopen('php://stdout', 'w');
    }

    $reader = new DataReader($in);
    solve($reader, $out);

    fclose($in);
    fclose($out);
}

main();
