    $gIndex = strpos($s, 'G');
    $result = dfs($gIndex, $n, $k, $s, $used);
    $output .= ($result ? "YES" : "NO") . "\n";
}

function nextToken(&$input): string {
    global $tokenIndex, $tokens;
    if (!isset($tokens) || $tokenIndex >= count($tokens)) {
        $line = fgets($input);
        if ($line === false) {
            return "";
        }
        $tokens = preg_split('/\s+/', trim($line), -1, PREG_SPLIT_NO_EMPTY);
        $tokenIndex = 0;
    }
    if ($tokenIndex < count($tokens)) {
        return $tokens[$tokenIndex++];
    }
    return "";
}

